<script setup lang="ts">
import{ref,watch,onBeforeUnmount}from'vue';import{v1}from'../api';
interface Item{id:string;text:string;attachmentIds:string[]}
const props=defineProps<{runId:string;active:boolean}>(),emit=defineEmits<{(e:'sent',runId:string):void}>();
const data=ref<{items:Item[];paused:boolean}>({items:[],paused:false}),busy=ref(false),error=ref(''),editId=ref(''),draft=ref('');let generation=0,timer:ReturnType<typeof setTimeout>|undefined;
async function refresh(){const g=generation;try{const next=await v1<typeof data.value>(`/api/v1/runs/${props.runId}/queue`);if(g===generation){data.value=next;error.value='';}}catch(e){if(g===generation)error.value=String(e);}}
async function poll(g:number){await refresh();if(g===generation&&props.active)timer=setTimeout(()=>poll(g),1500);}
watch([()=>props.runId,()=>props.active],([id],previous)=>{generation++;clearTimeout(timer);if(id!==previous?.[0]){editId.value='';data.value={items:[],paused:false};}void poll(generation);},{immediate:true});
async function mutate(body:Record<string,unknown>){if(busy.value)return;busy.value=true;error.value='';const id=props.runId,g=generation;try{const result=await v1<typeof data.value>(`/api/v1/runs/${id}/queue`,{method:'PATCH',body:JSON.stringify(body)});if(g===generation){data.value=result;editId.value='';}}catch(e){if(g===generation)error.value=String(e);}finally{busy.value=false;}}
async function send(item:Item){if(busy.value)return;busy.value=true;const id=props.runId;try{const r=await v1<{runId:string}>(`/api/v1/runs/${id}/queue/send`,{method:'POST',body:JSON.stringify({itemId:item.id})});if(id===props.runId){await refresh();emit('sent',r.runId);}}catch(e){error.value=String(e);}finally{busy.value=false;}}
onBeforeUnmount(()=>{generation++;clearTimeout(timer);});defineExpose({refresh});
</script>
<template><section v-if="data.items.length||error" class="queue-panel" aria-label="排队消息"><header><strong>排队消息 · {{data.items.length}}</strong><button class="text-btn" :disabled="busy" @click="mutate({paused:!data.paused})">{{data.paused?'恢复自动处理':'暂停自动处理'}}</button></header><p v-if="data.paused" class="muted">队列已暂停，可选一条发送。</p><p v-if="error" role="alert">{{error}}</p><ol><li v-for="(item,i) in data.items" :key="item.id"><template v-if="editId!==item.id"><span>{{item.text}}</span><small v-if="item.attachmentIds.length">{{item.attachmentIds.length}}张图片</small><div class="queue-actions"><button class="text-btn" :disabled="busy||i===0" aria-label="上移排队消息" @click="mutate({itemId:item.id,action:'up'})">↑</button><button class="text-btn" :disabled="busy||i===data.items.length-1" aria-label="下移排队消息" @click="mutate({itemId:item.id,action:'down'})">↓</button><button class="text-btn" :disabled="busy" @click="editId=item.id;draft=item.text">编辑</button><button class="text-btn" :disabled="busy" @click="send(item)">{{active?'发送补充':'开始处理'}}</button><button class="text-btn" :disabled="busy" aria-label="移除排队消息" @click="mutate({itemId:item.id,action:'delete'})">×</button></div></template><form v-else @submit.prevent="mutate({itemId:item.id,action:'edit',text:draft})"><textarea v-model="draft" aria-label="编辑排队消息" maxlength="20000"></textarea><button class="btn" :disabled="busy||!draft.trim()">保存</button><button class="text-btn" type="button" @click="editId=''">取消</button></form></li></ol></section></template>
<style scoped>.queue-panel{width:var(--conversation-content-width);margin:0 auto 8px;border:1px solid var(--border);border-radius:12px;padding:12px;background:var(--bg-card);font-size:12px}header{display:flex;justify-content:space-between;align-items:center;gap:12px}header strong{font-weight:500}.queue-panel ol{list-style:none;margin:8px 0 0;padding:0;max-height:180px;overflow:auto}.queue-panel li{display:flex;flex-wrap:wrap;align-items:center;gap:8px;border-top:1px solid var(--border);padding:8px 0}.queue-panel li>span{flex:1;min-width:100px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.queue-actions{display:flex;gap:8px}.queue-panel form{width:100%}textarea{width:100%;background:var(--bg-input);color:var(--fg);border:1px solid var(--border);border-radius:6px;padding:8px}[role=alert]{color:var(--danger)}</style>
